<script setup lang="ts">
import {channelType,channelLabel,topupChannelName} from '../collectionMethods'
import { useI18n } from 'vue-i18n'
import type { OfferSet, TopupQuote } from '../marketingTypes'
import WalletAmountSplit from './WalletAmountSplit.vue'
import { dateTime } from '../format'
defineProps<{offers:OfferSet|null;quote:TopupQuote|null;expired:boolean;busy:boolean;timezone:string;paynowConfigured:boolean;confirmOnly?:boolean}>()
const selected=defineModel<string>('selected',{required:true}),channel=defineModel<string>('channel',{required:true}),{t}=useI18n()
defineEmits<{quote:[]}>()
</script>
<template><section v-if="offers" class="wallet-card"><h3>{{t(offers.campaignId?'wallet.marketing.activeRecharge':'wallet.marketing.ordinaryRecharge')}}</h3><p v-if="offers.campaignId&&offers.campaignName">{{offers.campaignName}}</p><p>{{t(offers.campaignId?'wallet.marketing.activeRechargeHint':'wallet.marketing.ordinaryRechargeHint')}}</p></section><fieldset v-if="offers" :disabled="busy"><legend>{{t('wallet.marketing.select')}}</legend><p v-if="!offers.offers.length" class="wallet-empty">{{t('wallet.marketing.noOffers')}}</p><label v-for="offer in offers.offers" :key="offer.id" class="wallet-offer-option"><input v-model="selected" type="radio" :value="offer.id"><WalletAmountSplit :principal="offer.principalCents" :bonus="offer.bonusCents" :total="offer.creditTotalCents" /></label></fieldset><fieldset v-if="offers" class="wallet-channel-picker" :disabled="busy"><legend>{{t('wallet.channel')}}</legend><label v-for="c in offers.channels" :key="c"><input v-model="channel" type="radio" :value="c" :disabled="channelType(c)==='paynow'&&!paynowConfigured">{{channelLabel(t,c,offers.channelLabels)}}</label><p v-if="offers.channels.some(c=>channelType(c)==='paynow')&&!paynowConfigured" class="wallet-warning">{{t('wallet.marketing.paynowSetup')}}</p></fieldset><button v-if="!confirmOnly" type="button" :disabled="busy||!selected||(channelType(channel)==='paynow'&&!paynowConfigured)" @click="$emit('quote')">{{t('wallet.marketing.quote')}}</button><section v-if="quote&&!confirmOnly" class="wallet-card"><WalletAmountSplit :principal="quote.principalCents" :bonus="quote.bonusCents" :total="quote.creditTotalCents" /><p :class="{'wallet-warning':expired}">{{expired?t('wallet.marketing.expired'):t('wallet.marketing.expires')+' '+dateTime(quote.expiresAt,timezone)}}</p></section></template>
